34: /// A data-structure that can be de-serialized from binary format by NBOR.
35: pub trait BorshDeserialize: Sized {
36:     /// Deserializes this instance from a given slice of bytes.
37:     /// Updates the buffer to point at the remaining bytes.
38:     fn deserialize(buf: &mut &[u8]) -> Result<Self> {
39:         Self::deserialize_reader(&mut *buf)
40:     }
41: 
42:     fn deserialize_reader<R: Read>(reader: &mut R) -> Result<Self>;

128: fn unexpected_eof_to_unexpected_length_of_input(e: Error) -> Error {
129:     if e.kind() == ErrorKind::UnexpectedEof {
130:         Error::new(ErrorKind::InvalidInput, ERROR_UNEXPECTED_LENGTH_OF_INPUT)
131:     } else {
132:         e
133:     }
134: }
135: 
136: impl BorshDeserialize for u8 {
137:     #[inline]
138:     fn deserialize_reader<R: Read>(reader: &mut R) -> Result<Self> {
139:         let mut buf = [0u8; 1];
140:         reader
141:             .read_exact(&mut buf)
142:             .map_err(unexpected_eof_to_unexpected_length_of_input)?;
143:         Ok(buf[0])
144:     }

187: macro_rules! impl_for_integer {
188:     ($type: ident) => {
189:         impl BorshDeserialize for $type {
190:             #[inline]
191:             fn deserialize_reader<R: Read>(reader: &mut R) -> Result<Self> {
192:                 let mut buf = [0u8; size_of::<$type>()];
193:                 reader
194:                     .read_exact(&mut buf)
195:                     .map_err(unexpected_eof_to_unexpected_length_of_input)?;
196:                 let res = $type::from_le_bytes(buf.try_into().unwrap());
197:                 Ok(res)
198:             }
199:         }
200:     };

1: use proc_macro2::TokenStream as TokenStream2;
2: use quote::quote;
3: use syn::{Fields, Ident, ItemStruct, WhereClause};
4: 
5: use crate::attribute_helpers::{contains_initialize_with, contains_skip};
6: 
7: pub fn struct_de(input: &ItemStruct, cratename: Ident) -> syn::Result<TokenStream2> {
8:     let name = &input.ident;
9:     let (impl_generics, ty_generics, where_clause) = input.generics.split_for_impl();
10:     let mut where_clause = where_clause.map_or_else(
11:         || WhereClause {
12:             where_token: Default::default(),
13:             predicates: Default::default(),
14:         },
15:         Clone::clone,
16:     );
17:     let init_method = contains_initialize_with(&input.attrs)?;
18:     let return_value = match &input.fields {
19:         Fields::Named(fields) => {
20:             let mut body = TokenStream2::new();
21:             for field in &fields.named {
22:                 let field_name = field.ident.as_ref().unwrap();
23:                 let delta = if contains_skip(&field.attrs) {
24:                     quote! {
25:                         #field_name: Default::default(),
26:                     }
27:                 } else {
28:                     let field_type = &field.ty;
29:                     where_clause.predicates.push(
30:                         syn::parse2(quote! {
31:                             #field_type: #cratename::BorshDeserialize
32:                         })
33:                         .unwrap(),
34:                     );
35: 
36:                     quote! {
37:                         #field_name: #cratename::BorshDeserialize::deserialize_reader(reader)?,
38:                     }
39:                 };
40:                 body.extend(delta);
41:             }
42:             quote! {
43:                 Self { #body }
44:             }
45:         }
46:         Fields::Unnamed(fields) => {
47:             let mut body = TokenStream2::new();
48:             for _ in 0..fields.unnamed.len() {
49:                 let delta = quote! {
50:                     #cratename::BorshDeserialize::deserialize_reader(reader)?,
51:                 };
52:                 body.extend(delta);
53:             }
54:             quote! {
55:                 Self( #body )
56:             }
57:         }
58:         Fields::Unit => {
59:             quote! {
60:                 Self {}
61:             }
62:         }
63:     };
64:     if let Some(method_ident) = init_method {
65:         Ok(quote! {
66:             impl #impl_generics #cratename::de::BorshDeserialize for #name #ty_generics #where_clause {
67:                 fn deserialize_reader<R: borsh::maybestd::io::Read>(reader: &mut R) -> ::core::result::Result<Self, #cratename::maybestd::io::Error> {
68:                     let mut return_value = #return_value;
69:                     return_value.#method_ident();
70:                     Ok(return_value)
71:                 }
72:             }
73:         })
74:     } else {
75:         Ok(quote! {
76:             impl #impl_generics #cratename::de::BorshDeserialize for #name #ty_generics #where_clause {
77:                 fn deserialize_reader<R: borsh::maybestd::io::Read>(reader: &mut R) -> ::core::result::Result<Self, #cratename::maybestd::io::Error> {
78:                     Ok(#return_value)
79:                 }
80:             }
81:         })
82:     }
83: }
